import { jsx as _jsx, jsxs as _jsxs } from "react/jsx-runtime";
import { describe, it, expect } from "vitest";
import { screen, render } from "@testing-library/react";
import { Panel } from "../Panel";
import { PanelHeader } from "../../panelHeader";
import { PanelContent } from "../PanelContent";
import { PanelFooter } from "../PanelFooter";
describe("Panel", () => {
    it("Should render panel when open is true", () => {
        render(_jsxs(Panel, { open: true, children: [_jsx(PanelHeader, { pageTitle: "Test Panel" }), _jsx(PanelContent, { children: "Test Content" })] }));
        expect(screen.getByText("Test Panel")).toBeInTheDocument();
        expect(screen.getByText("Test Content")).toBeInTheDocument();
    });
    it("Should not render panel when open is false", () => {
        render(_jsxs(Panel, { open: false, children: [_jsx(PanelHeader, { pageTitle: "Test Panel" }), _jsx(PanelContent, { children: "Test Content" })] }));
        expect(screen.queryByText("Test Panel")).not.toBeInTheDocument();
        expect(screen.queryByText("Test Content")).not.toBeInTheDocument();
    });
    it("Should render panel with all sections (header, content, footer)", () => {
        render(_jsxs(Panel, { open: true, children: [_jsx(PanelHeader, { pageTitle: "Test Panel" }), _jsx(PanelContent, { children: "Test Content" }), _jsx(PanelFooter, { children: "Test Footer" })] }));
        expect(screen.getByText("Test Panel")).toBeInTheDocument();
        expect(screen.getByText("Test Content")).toBeInTheDocument();
        expect(screen.getByText("Test Footer")).toBeInTheDocument();
    });
});
